mapper.update:

UPDATE msg_info SET
  delete_state = #{deleteState,jdbcType=BIGINT}
WHERE id = #{id,jdbcType=VARCHAR}

mapper.select:

SELECT

FROM msg_info
WHERE delete_state = 0

  AND message_title LIKE CONCAT('%', #{messageTitle,jdbcType=VARCHAR}, '%')


  AND message_type = #{messageType,jdbcType=CHAR}


  AND message_level = #{messageLevel,jdbcType=CHAR}


  AND business_type = #{businessType,jdbcType=CHAR}


  AND `status` = #{status,jdbcType=CHAR}


  AND sender_id = #{senderId,jdbcType=VARCHAR}


  AND create_user = #{createUser,jdbcType=VARCHAR}


  AND create_time BETWEEN #{createTimeStart,jdbcType=TIMESTAMP} AND #{createTimeEnd,jdbcType=TIMESTAMP}


  AND sender_time BETWEEN #{senderTimeStart,jdbcType=TIMESTAMP} AND #{senderTimeEnd,jdbcType=TIMESTAMP}


  AND expire_time BETWEEN #{expireTimeStart,jdbcType=TIMESTAMP} AND #{expireTimeEnd,jdbcType=TIMESTAMP}
